  const surKey = info.pct ? (info.reasons.length > 1 ? 'r-sat-me' : { Saturday: 'r-sat', Sunday: 'r-sun', 'Month end': 'r-monthend' }[info.reasons[0][0]]) : 'r-weekday';
  rows.push([info.pct ? `${info.reasons.map((r) => r[0]).join(' + ')} · +${info.pct} % on labour and stairs` : 'Date surcharge · none', sur, surKey]);
