// Three ways to do the same move: cheapest date, earliest date, another van arrangement.
function quoteOptions(input, D) {
  const base = quote(input, D);
  if (!base) return [];
  const out = [];
  const first = addDays(D.TODAY, D.NOTICE_DAYS);
  const from = input.date && input.date >= first ? input.date : first;
  let best = null;
  for (let i = -14; i <= 21; i++) {
    const s = addDays(from, i);
    const st = dateInfo(s, D).status;
    if (st !== 'open' && st !== 'surcharge') continue;
    const q = quote({ ...input, date: s }, D);
    if (!best || q.total < best.q.total - 1e-9 || (Math.abs(q.total - best.q.total) < 1e-9 && Math.abs(i) < Math.abs(best.i))) best = { s, q, i };
  }
  if (best) out.push({ id: 'cheap', title: 'Cheapest date', patch: { date: best.s }, total: best.q.total, why: `${fmtDate(best.s, false)}: ${best.q.info.pct ? '+' + best.q.info.pct + ' %' : 'standard rate'}. Nearest date within three weeks with the lowest total.` });
  let early = null;
  for (let s = first; s <= D.RANGE.to; s = addDays(s, 1)) { const st = dateInfo(s, D).status; if (st === 'open' || st === 'surcharge') { early = s; break; } }
  if (early) { const q = quote({ ...input, date: early }, D); out.push({ id: 'early', title: 'Earliest date', patch: { date: early }, total: q.total, why: `${fmtDate(early, false)}: first date with a free crew, ${D.NOTICE_DAYS} days’ notice.` }); }
  const cur = base.fit;
  const idx = D.VANS.indexOf(cur.vans[0]);
  let alt = null;
  if (cur.forced) alt = { vanId: '', trips: 1 };
  else if (cur.vans.length === 2) alt = { vanId: 'large', trips: 2 };
  else if (idx > 0 && input.vol <= D.VANS[idx - 1].m3 * 2) alt = { vanId: D.VANS[idx - 1].id, trips: 2 };
  else if (idx < D.VANS.length - 1) alt = { vanId: D.VANS[idx + 1].id, trips: 1 };
  if (alt) {
    const q = quote({ ...input, ...alt }, D);
    if (q) {
      const one = alt.trips === 1;
      const diff = q.total - base.total;
      const cmp = Math.abs(diff) < 0.005 ? 'Same total' : `${diff < 0 ? 'Cheaper' : 'Dearer'} by ${money(Math.abs(diff))}`;
      const why = one
        ? (cur.forced || cur.trips > 1 ? `One trip in the van that holds ${m3(input.vol)} m³, ${num(q.hours.hours, 1)} h. ${cmp}.` : `Room to spare: ${Math.round((input.vol / q.fit.cap) * 100)} % full instead of ${Math.round((input.vol / cur.cap) * 100)} %. ${cmp}.`)
        : `One van twice instead of ${cur.vans.length > 1 ? 'two vans' : 'a bigger van'}: ${num(q.hours.hours, 1)} h with the extra drive. ${cmp}.`;
      out.push({ id: 'van', title: one ? `${fitLine(q.fit)}, one trip` : fitLine(q.fit), patch: alt, total: q.total, why });
    }
  }
  return out;
}

// Things the person may have missed. Each: { id, text, why, fix: { label, patch | href } }
function quoteAlerts(input, D, flags = {}) {
  const out = [];
  const R = D.RATES;
  if (input.vol > D.MAX_M3) out.push({ id: 'survey', text: `Over ${D.MAX_M3} m³.`, why: 'Too much for two vans in a day.', fix: { label: 'Ask a person for a home survey', act: 'handover' } });
  const q = quote(input, D);
  if (q && q.fit.vans.length === 1 && q.fit.trips === 1) {
    const pct = Math.round((input.vol / q.fit.cap) * 100);
    const next = D.VANS[D.VANS.indexOf(q.fit.vans[0]) + 1];
    if (pct >= 90 && next) out.push({ id: 'full', text: `${q.fit.vans[0].name} ${pct} % full.`, why: 'Lists grow by about 5 % on the day: lamps, bags, plants.', fix: { label: `Use the ${next.name.toLowerCase()}`, patch: { vanId: next.id, trips: 1 } } });
  }
  if (input.floorsA > 0 && !input.liftA) out.push({ id: 'stA', text: `Stairs moving out: ${input.floorsA} floor${input.floorsA > 1 ? 's' : ''}, ${money(input.floorsA * R.perFloor)}.`, why: 'Charged when there is no lift.', fix: { label: 'There is a lift', patch: { liftA: true } } });
  if (input.floorsB > 0 && !input.liftB) out.push({ id: 'stB', text: `Stairs moving in: ${input.floorsB} floor${input.floorsB > 1 ? 's' : ''}, ${money(input.floorsB * R.perFloor)}.`, why: 'Charged when there is no lift.', fix: { label: 'There is a lift', patch: { liftB: true } } });
  if (input.date) {
    const i = dateInfo(input.date, D);
    if (i.status === 'surcharge') {
      let s = input.date, alt = null;
      for (let k = 1; k <= 10 && !alt; k++) for (const d of [addDays(s, -k), addDays(s, k)]) if (!alt && dateInfo(d, D).status === 'open') alt = d;
      out.push({ id: 'sur', text: `${i.reasons.map((r) => r[0]).join(' and ')} surcharge, +${i.pct} %.`, why: 'Weekends and the last two days of a month cost more.', fix: alt ? { label: `Move to ${fmtDate(alt, false)}`, patch: { date: alt } } : null });
    }
  }
  if (flags.storage) {
    const u = D.UNITS.find((x) => x.m3 >= input.vol) || D.UNITS[D.UNITS.length - 1];
    out.push({ id: 'store', text: `Storage between moves: ${num(u.m2, 1)} m² unit, ${money(u.week)} a week.`, why: `Holds ${num(u.m3, 1)} m³; the move is ${m3(input.vol)} m³.`, fix: { label: 'Storage sizes', href: 'storage' } });
  }
  return out;
}
function invAlerts(total, D) {
  const out = [];
  if (total > D.MAX_M3) out.push({ id: 'inv-survey', text: `${m3(total)} m³ is over ${D.MAX_M3} m³.`, why: 'Two vans cannot take it in one day.', fix: { label: 'Ask a person for a home survey', act: 'handover' } });
  else if (total > D.VANS[2].m3) out.push({ id: 'inv-two', text: `Over ${D.VANS[2].m3} m³: two vans.`, why: 'Large and medium van together, 7 crew.', fix: null });
  const f = vansFor(total, D.VANS, D.MAX_M3);
  if (f && !f.over && f.vans.length === 1) {
    const pct = Math.round((total / f.cap) * 100);
    if (pct >= 90) out.push({ id: 'inv-full', text: `${f.vans[0].name} ${pct} % full.`, why: 'Lists grow by about 5 % on the day. The next van up leaves room.', fix: null });
  }
  return out;
}

// ---- reading text ----
const WORDNUM = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, twelve: 12, twenty: 20, thirty: 30 };
const MONTHS = { jan: 0, january: 0, feb: 1, february: 1, mar: 2, march: 2, apr: 3, april: 3, may: 4, jun: 5, june: 5, jul: 6, july: 6, aug: 7, august: 7, sep: 8, sept: 8, september: 8, oct: 9, october: 9, nov: 10, november: 10, dec: 11, december: 11 };
const WDAYS = { sun: 0, sunday: 0, mon: 1, monday: 1, tue: 2, tues: 2, tuesday: 2, wed: 3, wednesday: 3, thu: 4, thur: 4, thurs: 4, thursday: 4, fri: 5, friday: 5, sat: 6, saturday: 6 };
function matchItem(text, D) {
  const t = ' ' + text.toLowerCase().replace(/[^a-z0-9 -]/g, ' ').replace(/\s+/g, ' ') + ' ';
  let best = null;
  for (const id in D.SYN) for (const w of D.SYN[id]) {
    if (t.includes(' ' + w + ' ') || t.includes(' ' + w + 's ') || t.includes(' ' + w + 'es ')) if (!best || w.length > best.w.length) best = { id, w };
  }
  return best;
}
// One line of a pasted list: "2 x double wardrobe", "sofa (3 seater)", "30 boxes", "piano".
function parseList(text, D) {
  const idx = itemIndex(D.ROOMS);
  return String(text).split(/\r?\n|;/).map((l) => l.trim()).filter(Boolean).slice(0, 60).map((line) => {
    let qty = 1;
    const l = line.toLowerCase();
    const m = l.match(/^(\d{1,3})\s*(x|×)?\s+/) || l.match(/^(\d{1,3})\s*(x|×)/) || l.match(/(?:x|×)\s*(\d{1,3})\b/) || l.match(/\b(\d{1,3})\s*$/);
    if (m) qty = parseInt(m[1], 10);
    else { const w = l.match(/^(a|an|one|two|three|four|five|six|seven|eight|nine|ten|twelve|twenty|thirty)\b/); if (w) qty = WORDNUM[w[1]]; }
    const hit = matchItem(l.replace(/\d+/g, ' '), D);
    return hit ? { line, id: hit.id, name: idx[hit.id].name, qty: Math.min(qty, 99), vol: idx[hit.id].vol } : { line, id: null, qty, vol: 0 };
  });
}
function nextWeekday(from, wd, D) {
  let s = from;
  for (let i = 0; i < 7; i++) { if (D0(s).getUTCDay() === wd) return s; s = addDays(s, 1); }
  return s;
}
// "2 bed flat, 3rd floor no lift, Sat 14 Nov, 8 miles" → fields + chips + what was not read
function parseMove(text, D) {
  const f = {};
  const chips = [];
  const unread = [];
  const flags = {};
  const segs = String(text).toLowerCase().replace(/ to | then | and /g, ',').split(/[,;.\n]+/).map((s) => s.trim()).filter(Boolean);
  let floorN = 0;
  for (const seg of segs) {
    let used = false;
    let m;
    if ((m = seg.match(/(\d+(?:\.\d+)?)\s*(?:m3|m³|cubic\s*met(?:re|er)s?|cbm)/))) { f.vol = parseFloat(m[1]); chips.push(['vol', `Volume ${m3(f.vol)} m³`]); used = true; }
    else if ((m = seg.match(/\b(studio|bedsit)\b/)) || (m = seg.match(/\b(\d|one|two|three|four|five)[\s-]*(?:bed|bedroom|bedrooms|br)\b/))) {
      const n = m[1] === 'studio' || m[1] === 'bedsit' ? 0 : (WORDNUM[m[1]] || parseInt(m[1], 10));
      const h = D.HOMES[Math.min(n, 5)];
      f.vol = h.m3; f.home = h.id; chips.push(['vol', `Volume ${h.m3} m³ (${h.label})`]); used = true;
    }
    if ((m = seg.match(/(\d+(?:\.\d+)?)\s*(?:mi|miles?)\b/))) { f.miles = parseFloat(m[1]); chips.push(['miles', `Distance ${num(f.miles)} mi`]); used = true; }
    else if ((m = seg.match(/(\d+(?:\.\d+)?)\s*(?:km|kilomet(?:re|er)s?)\b/))) { f.miles = Math.round(parseFloat(m[1]) * 0.621); chips.push(['miles', `Distance ${f.miles} mi (from ${m[1]} km)`]); used = true; }
    if ((m = seg.match(/\b(ground|basement|\d{1,2})(?:st|nd|rd|th)?\s*floor\b/)) || (m = seg.match(/\bfloor\s*(\d{1,2})\b/))) {
      const n = m[1] === 'ground' || m[1] === 'basement' ? 0 : parseInt(m[1], 10);
      const lift = /\bno lift|without (?:a )?lift|no elevator/.test(seg) ? false : /\blift|elevator/.test(seg) ? true : false;
      const k = floorN === 0 ? 'A' : 'B';
      f['floors' + k] = Math.min(n, 10); f['lift' + k] = lift; floorN++;
      chips.push(['floors' + k, `${k === 'A' ? 'Moving out' : 'Moving in'}: ${n === 0 ? 'ground' : 'floor ' + n}${n ? (lift ? ', lift' : ', no lift') : ''}`]);
      used = true;
    } else if (/\bno lift|without (?:a )?lift/.test(seg) && floorN > 0) { used = true; }
    // dates: "14 nov", "nov 14", "sat 14 nov", "saturday", "next saturday", "2026-11-14"
    let iso = null;
    if ((m = seg.match(/\b(20\d\d-\d\d-\d\d)\b/))) iso = m[1];
    else if ((m = seg.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sept?(?:ember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\b/)) || (m = seg.match(/\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sept?(?:ember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?\b/))) {
      const day = parseInt(/\d/.test(m[1]) ? m[1] : m[2], 10);
      const mon = MONTHS[/\d/.test(m[1]) ? m[2] : m[1]];
      const y = mon >= 10 ? 2026 : 2027;
      if (day >= 1 && day <= daysInMonth(y, mon)) iso = `${y}-${String(mon + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    } else if ((m = seg.match(/\b(next week\s+|next\s+|this\s+)?(sun(?:day)?|mon(?:day)?|tue(?:s|sday)?|wed(?:nesday)?|thu(?:r|rs|rsday)?|fri(?:day)?|sat(?:urday)?)\b/))) {
      const wd = WDAYS[m[2]];
      let start = addDays(D.TODAY, 1);
      const dow = (D0(D.TODAY).getUTCDay() + 6) % 7; // Monday = 0
      if (m[1] && /next/.test(m[1])) start = addDays(D.TODAY, 7 - dow); // Monday of next week
      iso = nextWeekday(start, wd, D);
    }
    if (iso) { f.date = iso; chips.push(['date', `Date ${fmtDate(iso, false)}`]); used = true; }
    if (/\bpack(?:ing)? service|you pack|pack for (?:us|me)|packing\b/.test(seg)) { f.packing = true; chips.push(['packing', 'Packing service']); used = true; }
    if (/\bstorage|store\b|keys later|between (?:homes|moves)/.test(seg)) { flags.storage = true; chips.push(['storage', 'Storage needed']); used = true; }
    if (!used && !/^(flat|house|from|my|we|i|please|move|moving)$/.test(seg)) unread.push(seg);
  }
  return { fields: f, chips, unread, flags };
}

// "Will a fridge-freezer fit the small van?"
function fitAnswer(itemId, vanId, D) {
  const idx = itemIndex(D.ROOMS);
  const it = idx[itemId];
  const vans = vanId ? D.VANS.filter((v) => v.id === vanId) : D.VANS;
  const size = D.SIZE[itemId];
  return vans.map((v) => {
    if (!size) return { van: v, ok: it.vol <= v.m3, line: `${v.name}: yes. ${it.name} is about ${num(it.vol, it.vol < 0.1 ? 2 : 1)} m³.` };
    const [len, upright] = size;
    if (upright) {
      const ok = len <= v.hgt;
      return { van: v, ok, line: `${v.name}: ${ok ? 'yes' : 'no'}. ${it.name} is ${len} m tall and travels upright; load height ${v.hgt} m.` };
    }
    const diag = Math.sqrt(v.len * v.len + v.hgt * v.hgt);
    const ok = len <= v.len || len <= diag;
    return { van: v, ok, line: `${v.name}: ${ok ? 'yes' : 'no'}. ${it.name} is ${len} m at its longest; load length ${v.len} m.` };
  });
}

// van side view, 1 m = 100 units, same scale for every van
function vanSvg(v, { fill = null, label = true, idp = '' } = {}) {
  const S = 100, cab = v.len > 5 ? 170 : 140, pad = 24;
  const W = cab + v.len * S + pad * 2 + 70, boxH = v.hgt * S, base = 60;
  const H = boxH + base + 60;
  const x0 = pad, bx = x0 + cab, by = H - base - boxH, gy = H - 38;
  const cabTop = gy - 22 - Math.min(boxH * 0.78, 180);
  const lw = v.len * S;
  return `<svg class="van" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="width:${((W / 928) * 100).toFixed(2)}%" role="img" aria-labelledby="${idp}t">
  <title id="${idp}t">${esc(v.name)}, load space ${v.len} m long, ${v.wid} m wide, ${v.hgt} m high: ${v.m3} m³</title>
  <line class="ground" x1="0" y1="${gy + 18}" x2="${W}" y2="${gy + 18}"/>
  <path class="cab" d="M${bx} ${gy - 4} L${x0} ${gy - 4} L${x0} ${cabTop + 48} L${x0 + 34} ${cabTop} L${bx} ${cabTop} Z"/>
  <rect class="win" x="${x0 + 28}" y="${cabTop + 14}" width="${cab - 52}" height="34"/>
  ${fill === null ? '' : `<rect class="fill" x="${bx}" y="${by}" width="${lw}" height="${boxH}" style="transform:scaleX(${fill})"/>`}
  <rect class="box" x="${bx}" y="${by}" width="${lw}" height="${boxH}"/>
  <circle class="wheel" cx="${x0 + cab * 0.45}" cy="${gy}" r="18"/><circle class="wheel" cx="${bx + lw - 70}" cy="${gy}" r="18"/>${v.len > 5 ? `<circle class="wheel" cx="${bx + lw - 112}" cy="${gy}" r="18"/>` : ''}
  ${label ? `<g class="dim"><line x1="${bx}" y1="${by - 18}" x2="${bx + lw}" y2="${by - 18}"/><line x1="${bx}" y1="${by - 26}" x2="${bx}" y2="${by - 10}"/><line x1="${bx + lw}" y1="${by - 26}" x2="${bx + lw}" y2="${by - 10}"/>
  <text x="${bx + lw / 2}" y="${by - 28}" text-anchor="middle">${v.len.toFixed(1)} m</text>
  <line x1="${bx + lw + 18}" y1="${by}" x2="${bx + lw + 18}" y2="${by + boxH}"/><line x1="${bx + lw + 10}" y1="${by}" x2="${bx + lw + 26}" y2="${by}"/><line x1="${bx + lw + 10}" y1="${by + boxH}" x2="${bx + lw + 26}" y2="${by + boxH}"/>
  <text x="${bx + lw + 32}" y="${by + boxH / 2 + 6}">${v.hgt.toFixed(2)} m</text></g>` : ''}
</svg>`;
}


